var t=`0372-birchermuesli`;var n=`world-0372`;var r=`CH`;var o=`western-europe`;var l=4;var s=198;var a={en:`Birchermüesli`,ua:`Бірхермюслі`};var g={en:`A traditional Switzerland dish made with rolled oats, whole cow milk, greek yogurt, lemon juice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Швейцарія. Основні інгредієнти: вівсяні пластівці, цільне коров'яче молоко, грецький йогурт, лимонний сік. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`rolled-oats`,310,`g`],[`whole-cow-milk`,450,`ml`],[`greek-yogurt`,160,`g`],[`lemon-juice`,20,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 180 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 180 хвилин.`,t:[`rapid-chilling`],m:180,i:[]},{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:5,i:[[`apple`,330,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`hazelnut`,100,`g`],[`honey`,60,`g`],[`raisin`,75,`g`]]}];var d={slug:t,id:n,country:`CH`,region:o,servings:4,minutes:198,title:a,text:g,steps:u};export{r as country,d as default,n as id,s as minutes,o as region,l as servings,t as slug,u as steps,g as text,a as title};